97	/** Bundles every entry point under `srcDir` into `distDir`, preserving its subdirectory structure (e.g. `mcp/github.ts` -> `<distDir>/mcp/github.ts`). */
98	async function bundleTree(srcDir: string, distDir: string, excludeDirs: ReadonlySet<string> = new Set()): Promise<void> {
99	  const entrypoints = collectEntryPoints(srcDir, excludeDirs);
100	  rmSync(distDir, { recursive: true, force: true });
101	
102	  // Build each deployable entry point independently. Imported implementation
103	  // modules live under excluded `lib/` directories and are inlined here.
104	  for (const entrypoint of entrypoints) {
105	    const result = await Bun.build({
106	      entrypoints: [entrypoint],
107	      outdir: distDir,
108	      root: srcDir,
109	      target: "bun",
110	      format: "esm",
111	      naming: "[dir]/[name].ts",
112	      external: RUNTIME_INSTALLED,
113	    });
114	    if (!result.success) {
115	      console.error(`build-dist: bundling failed for ${entrypoint}:`);
116	      for (const log of result.logs) console.error(log);
117	      process.exit(1);
118	    }
119	  }
120	
121	  console.log(`build-dist: bundled ${entrypoints.length} script(s): ${srcDir} -> ${distDir}`);
122	}
